<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Bulanan Eka Fashion</title><style>body{font-family:Arial,sans-serif;color:#222;margin:36px;font-size:12px}h1{margin:0;font-size:22px}h2{font-size:16px;margin:4px 0 22px;color:#555}.head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:14px;margin-bottom:18px}.meta{text-align:right;color:#555}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px}.box{border:1px solid #bbb;padding:12px}.box small{display:block;color:#666}.box strong{display:block;font-size:17px;margin-top:5px}h3{font-size:14px;border-bottom:1px solid #999;padding-bottom:6px;margin-top:22px}table{width:100%;border-collapse:collapse;margin-bottom:16px}th,td{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eee}td.num,th.num{text-align:right}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.note{color:#666;margin-top:26px;font-size:10px}@media print{body{margin:15mm}.actions{display:none}}@media(max-width:700px){.summary,.two{grid-template-columns:1fr 1fr}}</style></head><body><div class="actions"><button onclick="window.print()">Cetak / Simpan PDF</button></div><div class="head"><div><h1>EKA FASHION</h1><h2>Laporan Penjualan Bulanan</h2></div><div class="meta">Periode<br><strong><?=date('F Y',strtotime($start))?></strong><br>Dicetak: <?=date('d/m/Y H:i')?></div></div><div class="summary"><div class="box"><small>Total transaksi</small><strong><?=number_format($summary['transaksi'])?></strong></div><div class="box"><small>Total pendapatan</small><strong><?=rupiah($summary['pendapatan'])?></strong></div><div class="box"><small>Produk terjual</small><strong><?=number_format($summary['produk_terjual'])?> item</strong></div><div class="box"><small>Rata-rata transaksi</small><strong><?=rupiah($summary['rata_rata'])?></strong></div></div><div class="two"><section><h3>Produk terlaris</h3><table><thead><tr><th>Produk</th><th class="num">Terjual</th><th class="num">Pendapatan</th></tr></thead><tbody><?php foreach($topProducts as $p):?><tr><td><?=e($p['nama'])?></td><td class="num"><?=number_format($p['jumlah'])?></td><td class="num"><?=rupiah($p['pendapatan'])?></td></tr><?php endforeach;?><?php if(!$topProducts):?><tr><td colspan="3">Belum ada penjualan.</td></tr><?php endif;?></tbody></table></section><section><h3>Posisi stok</h3><table><tbody><tr><td>Total jenis produk</td><td class="num"><?=number_format($stock['jenis'])?></td></tr><tr><td>Total unit stok</td><td class="num"><?=number_format($stock['unit'])?></td></tr><tr><td>Nilai stok</td><td class="num"><?=rupiah($stock['nilai'])?></td></tr><tr><td>Produk stok menipis</td><td class="num"><?=number_format(count($lowStock))?></td></tr></tbody></table></section></div><h3>Rincian transaksi</h3><table><thead><tr><th>No</th><th>Tanggal</th><th>Kasir</th><th>Pelanggan</th><th>Pembayaran</th><th class="num">Total</th></tr></thead><tbody><?php foreach($transactions as $r):?><tr><td>#<?=$r['id']?></td><td><?=date('d/m/Y H:i',strtotime($r['tanggal']))?></td><td><?=e($r['kasir'])?></td><td><?=e($r['pelanggan'])?></td><td><?=strtoupper(e($r['payment_method']))?></td><td class="num"><?=rupiah($r['total'])?></td></tr><?php endforeach;?><?php if(!$transactions):?><tr><td colspan="6">Belum ada transaksi pada periode ini.</td></tr><?php endif;?></tbody></table><?php if($lowStock):?><h3>Daftar stok menipis</h3><table><thead><tr><th>Produk</th><th class="num">Stok</th><th class="num">Nilai stok</th></tr></thead><tbody><?php foreach($lowStock as $p):?><tr><td><?=e($p['nama'])?></td><td class="num"><?=number_format($p['stok'])?></td><td class="num"><?=rupiah($p['stok']*$p['harga'])?></td></tr><?php endforeach;?></tbody></table><?php endif;?><div class="note">Dokumen ini dibuat oleh sistem Eka Fashion dan dapat disimpan sebagai PDF melalui menu cetak browser.</div></body></html>
